```apex
public class ExchangeRateClient {

    public class ExchangeRateException extends Exception {}

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        // Validate quote set
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('Quote currency set must not be null or empty.');
        }

        // Normalise and validate base currency
        String base = normalise(baseCurrency);
        if (!isValidCurrencyCode(base)) {
            throw new ExchangeRateException('Invalid base currency code: ' + String.valueOf(baseCurrency));
        }

        // Normalise and validate quote currencies
        Set<String> normalisedQuotes = new Set<String>();
        for (String code : quoteCurrencies) {
            String normalised = normalise(code);
            if (!isValidCurrencyCode(normalised)) {
                throw new ExchangeRateException('Invalid quote currency code: ' + String.valueOf(code));
            }
            normalisedQuotes.add(normalised);
        }

        // Build the symbols query parameter
        String symbols = String.join(normalisedQuotes, ',');

        // Execute request (with single retry on 503)
        HttpResponse res = executeRequest(base, symbols);
        if (res.getStatusCode() == 503) {
            res = executeRequest(base, symbols);
        }

        if (res.getStatusCode() != 200) {
            throw new ExchangeRateException('API returned unexpected status code: ' + res.getStatusCode());
        }

        // Parse and extract rates
        return parseResponse(res.getBody(), normalisedQuotes);
    }

    private static String normalise(String code) {
        if (code == null) {
            return '';
        }
        return code.trim().toUpperCase();
    }

    private static Boolean isValidCurrencyCode(String code) {
        return code != null && code.matches('^[A-Z]{3}$');
    }

    private static HttpResponse executeRequest(String base, String symbols) {
        HttpRequest req = new HttpRequest();
        req.setEndpoint('callout:FB_Exchange_Rates/v1/latest?base=' + base + '&symbols=' + symbols);
        req.setMethod('GET');
        req.setHeader('Accept', 'application/json');
        Http h = new Http();
        return h.send(req);
    }

    private static Map<String, Decimal> parseResponse(String body, Set<String> requestedCodes) {
        Map<String, Object> responseMap;
        try {
            responseMap = (Map<String, Object>) JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new ExchangeRateException('Unable to parse response body as JSON: ' + e.getMessage());
        }

        if (responseMap == null) {
            throw new ExchangeRateException('Response body is not a valid JSON object.');
        }

        Object ratesObj = responseMap.get('rates');
        if (ratesObj == null) {
            throw new ExchangeRateException('Response does not contain a "rates" field.');
        }

        Map<String, Object> ratesMap;
        try {
            ratesMap = (Map<String, Object>) ratesObj;
        } catch (Exception e) {
            throw new ExchangeRateException('Response "rates" field is not a JSON object.');
        }

        Map<String, Decimal> result = new Map<String, Decimal>();
        for (String code : requestedCodes) {
            Object rateValue = ratesMap.get(code);
            if (rateValue == null) {
                throw new ExchangeRateException('No rate found for requested currency code: ' + code);
            }
            Decimal rate;
            if (rateValue instanceof Integer) {
                rate = (Decimal)(Integer) rateValue;
            } else if (rateValue instanceof Decimal) {
                rate = (Decimal) rateValue;
            } else {
                throw new ExchangeRateException('Invalid rate value type for currency code: ' + code);
            }
            result.put(code, rate);
        }

        return result;
    }
}
```

